/**
 * S03 flag-off golden (docs/implementation/agent-intelligence/S03-prompt-caching.md).
 *
 * The committed snapshot __snapshots__/cached-prompt-flag-off.base.json was
 * generated by running this exact file against an unmodified export of base
 * 7224f40d69cf816a49139a30092cbf92551d2a8e (origin/main on 25 Oct 2026, whose
 * legacy prompt carries 962e877's group-agent wording; `git archive` of the
 * base, this file copied in, node_modules symlinked, `vitest run --update
 * <this file>`). The earlier wave A golden was taken at base 6d00b80, before
 * 962e877 changed the legacy prompt. With TIREH_CACHED_PROMPT and
 * TIREH_PROMPT_SYSTEM_TAIL unset, every later commit must reproduce it byte
 * for byte. Never regenerate it with `-u`. TIREH_PROMPT_SYSTEM_TAIL alone must
 * also reproduce it, because the tail arm needs the cached prompt.
 *
 * Only base-era APIs are used here, so the same file runs unchanged at the base.
 */
import { afterEach, describe, expect, it, vi } from 'vitest';
import { AnthropicLLM, type LLMRequest } from '../llm';
import { PersonaGateway, type RuntimePrivacyState } from '../gateway';
import { InMemoryUpdateDeduper, type NewMemory } from '../memory/store';
import type { TelegramUpdate } from '../telegram/client';
import type { MemoryRecord } from '../types';
import { GAMEEND_CHAT, LEADS_CHAT, TG, fakeVoice, makeGateway, memory } from './fixtures';

const provider = vi.hoisted(() => ({ calls: [] as unknown[], create: vi.fn(), stream: vi.fn() }));

vi.mock('@anthropic-ai/sdk', () => ({
  default: class {
    messages = { create: provider.create, stream: provider.stream };
  },
}));

const SNAPSHOT = './__snapshots__/cached-prompt-flag-off.base.json';
const NOW = new Date('2026-10-19T10:00:00Z');
const json = <T>(value: T): T => JSON.parse(JSON.stringify(value)) as T;

afterEach(() => {
  vi.useRealTimers();
  vi.unstubAllEnvs();
});

/** Fixed update and message ids, so repeated runs in one process are identical. */
function updates() {
  let id = 1;
  const message = (chatId: number, chatType: 'private' | 'supergroup', from: number, text: string) => ({
    update_id: id, message: { message_id: 100 + id++, from: { id: from, is_bot: false, first_name: 'x' }, chat: { id: chatId, type: chatType, ...(chatType === 'supergroup' ? { title: 'g' } : {}) }, date: 0, text },
  }) as TelegramUpdate;
  return {
    dm: (from: number, text: string) => message(from, 'private', from, text),
    group: (chatId: number, from: number, text: string) => message(chatId, 'supergroup', from, text),
  };
}

function seed(record: MemoryRecord): NewMemory {
  return Object.fromEntries(Object.entries(record).filter(([key]) => !['id', 'createdAt', 'updatedAt'].includes(key))) as NewMemory;
}

type Recorded = { replyPrompts: string[]; replyRequests: unknown[] };
const recorded = (llm: { replyPrompts: string[]; replyRequests: LLMRequest[] }): Recorded => ({ replyPrompts: [...llm.replyPrompts], replyRequests: json(llm.replyRequests) });

async function gatewayScenarios(): Promise<Record<string, Recorded>> {
  vi.useFakeTimers({ toFake: ['Date'] });
  vi.setSystemTime(NOW);
  const out: Record<string, Recorded> = {};

  {
    const u = updates();
    const ctx = makeGateway();
    await ctx.memories.add(seed(memory({ content: 'Reza prefers short standups', scope: { kind: 'private', personId: 'reza' }, aboutPersonIds: ['reza'] })));
    ctx.llm.nextReply = 'Short standups it is.';
    await ctx.gateway.handleUpdate('aria', u.dm(TG.reza, 'How should we run standups?'));
    ctx.llm.nextReply = 'Fifteen minutes at most.';
    await ctx.gateway.handleUpdate('aria', u.dm(TG.reza, 'And how long should standups be?'));
    out['1 private reza with a private memory, then history replay'] = recorded(ctx.llm);
  }
  {
    const u = updates();
    const ctx = makeGateway();
    await ctx.gateway.handleUpdate('aria', u.dm(TG.parastoo, 'What is on my plate today?'));
    out['2 private parastoo'] = recorded(ctx.llm);
  }
  {
    const u = updates();
    const ctx = makeGateway();
    await ctx.memories.add(seed(memory({ content: 'Tutorial goes to 3 steps', scope: { kind: 'group', groupId: 'gameend-team' }, source: { personId: 'milad', chatKind: 'group', groupId: 'gameend-team', at: new Date('2026-10-11T09:00:00Z') } })));
    await ctx.gateway.handleUpdate('aria', u.group(GAMEEND_CHAT, TG.milad, 'I pushed the new build'));
    await ctx.gateway.handleUpdate('aria', u.group(GAMEEND_CHAT, TG.parastoo, 'Aria, what did we decide about the tutorial?'));
    out['3 addressed group turn after an unaddressed message'] = recorded(ctx.llm);
  }
  {
    const u = updates();
    const ctx = makeGateway();
    ctx.org.getGroup('leads')!.hasGuests = true;
    await ctx.memories.add(seed(memory({ content: 'Leads think the budget is tight', scope: { kind: 'group', groupId: 'leads' }, source: { personId: 'parastoo', chatKind: 'group', groupId: 'leads', at: new Date('2026-10-11T09:00:00Z') } })));
    await ctx.gateway.handleUpdate('aria', u.group(LEADS_CHAT, TG.reza, 'Aria, hello there'));
    await ctx.gateway.handleUpdate('aria', u.group(LEADS_CHAT, TG.parastoo, 'Aria, how is the budget?'));
    out['4 hasGuests group'] = recorded(ctx.llm);
  }
  {
    const h = makeGateway();
    const state = (space: string): RuntimePrivacyState => ({ revision: `${space}-v1`, memoryEnabled: true, historyEnabled: true,
      context: space === 'personal' ? ['SAVED_CONTEXT_CANARY likes green tea', 'Walks every morning'] : ['WORK_CONTEXT_CANARY'], priorityContext: ['Reply briefly.'] });
    const gateway = new PersonaGateway({ ...h, voice: null, botFor: () => h.bot, deduper: new InMemoryUpdateDeduper(),
      runtimePrivacy: { read: async (_agent, _person, space) => state(space ?? 'work'), validateAudience: async () => true } });
    h.llm.nextReply = 'Hello again.';
    await gateway.converse('aria', 'reza', 'hello', { space: 'personal' });
    h.llm.nextReply = 'Green tea, then.';
    await gateway.converse('aria', 'reza', 'what tea should I have?', { space: 'personal' });
    out['5 personal converse with saved context'] = recorded(h.llm);
  }
  {
    const ctx = makeGateway();
    await ctx.memories.add(seed(memory({ content: 'Reza prefers short calls', scope: { kind: 'private', personId: 'reza' }, aboutPersonIds: ['reza'] })));
    const parts: string[] = [];
    for await (const part of ctx.gateway.liveTurn('aria', 'reza', [{ role: 'user', content: 'Can we talk about calls?' }])) parts.push(part);
    for await (const part of ctx.gateway.liveTurn('aria', 'reza', [{ role: 'user', content: 'Can we talk about calls?' }, { role: 'assistant', content: parts.join('') }, { role: 'user', content: 'Keep it short.' }])) parts.push(part);
    out['6 liveTurn'] = recorded(ctx.llm);
  }
  {
    const u = updates();
    const ctx = makeGateway({ voice: fakeVoice() });
    ctx.llm.nextReply = 'The meeting starts at ten.';
    await ctx.gateway.handleUpdate('aria', u.dm(TG.reza, 'can you send voice message'));
    out['7 voice reply format'] = recorded(ctx.llm);
  }
  {
    const u = updates();
    const ctx = makeGateway();
    await ctx.memories.add(seed(memory({ content: 'GameEnd launch is Feb 20', topic: 'launch', type: 'decision', scope: { kind: 'project', projectId: 'gameend' }, source: { personId: 'parastoo', chatKind: 'private', at: new Date('2026-10-12T09:00:00Z') } })));
    await ctx.memories.add(seed(memory({ content: 'GameEnd launch is March 5', topic: 'launch', type: 'decision', scope: { kind: 'project', projectId: 'gameend' } })));
    await ctx.gateway.handleUpdate('aria', u.dm(TG.parastoo, 'When is the GameEnd launch?'));
    out['8 memory conflict'] = recorded(ctx.llm);
  }
  vi.useRealTimers();
  return out;
}

const RULES_SYSTEM = 'You are a fixture persona.\n<rules>\n- Be brief.\n</rules>\n\n## This turn\nToday is 2026-10-19.';

async function anthropicBodies(): Promise<Record<string, unknown>> {
  const answer = { stop_reason: 'end_turn', content: [{ type: 'text', text: 'fixture answer' }], usage: { input_tokens: 3, output_tokens: 2 } };
  provider.create.mockReset();
  provider.stream.mockReset();
  provider.create.mockImplementation(async (body: unknown, options?: unknown) => { provider.calls.push(json({ create: body, options: options ?? null })); return answer; });
  provider.stream.mockImplementation((body: unknown, options?: unknown) => {
    provider.calls.push(json({ stream: body, options: options ?? null }));
    return (async function* () {
      yield { type: 'message_start', message: { usage: { input_tokens: 4, output_tokens: 0 } } };
      yield { type: 'content_block_delta', delta: { type: 'text_delta', text: 'streamed' } };
      yield { type: 'message_delta', delta: { stop_reason: 'end_turn' }, usage: { output_tokens: 1 } };
      yield { type: 'message_stop' };
    })();
  });
  const images = [{ mimeType: 'image/png' as const, data: 'synthetic-image-bytes' }];
  const variants: Record<string, LLMRequest['messages']> = {
    text: [{ role: 'user', content: 'first' }, { role: 'assistant', content: 'reply' }, { role: 'user', content: 'latest' }],
    images: [{ role: 'user', content: 'before' }, { role: 'assistant', content: 'ok' }, { role: 'user', content: 'Describe this.', images }],
    'image only': [{ role: 'user', content: '', images }],
  };
  const out: Record<string, unknown> = {};
  const record = async (name: string, run: () => Promise<unknown>) => {
    provider.calls = [];
    const result = await run();
    out[name] = { result, calls: provider.calls };
  };
  const llm = new AnthropicLLM('fixture-key', 'claude-haiku-5-5');
  for (const [label, messages] of Object.entries(variants)) {
    const request: LLMRequest = { system: RULES_SYSTEM, messages, maxTokens: 900, effort: 'low' };
    await record(`complete ${label}`, () => llm.complete(request));
    await record(`complete ${label} authorized`, () => llm.complete({ ...request, authorize: async () => true }));
    await record(`stream ${label}`, async () => { const parts: string[] = []; for await (const p of llm.stream(request)) parts.push(p); return parts; });
    await record(`completeWithWeb ${label}`, () => llm.completeWithWeb({ ...request, maxSearches: 2 }));
    provider.create.mockImplementationOnce(async (body: unknown, options?: unknown) => {
      provider.calls.push(json({ create: body, options: options ?? null }));
      return { stop_reason: 'pause_turn', content: [{ type: 'server_tool_use', id: 's1', name: 'web_search', input: { query: 'q' } }] };
    });
    await record(`completeWithWeb ${label} pause_turn`, () => llm.completeWithWeb({ ...request, maxSearches: 2 }));
  }
  return out;
}

async function golden(): Promise<string> {
  const value = { gateway: await gatewayScenarios(), anthropic: await anthropicBodies() };
  return `${JSON.stringify(value, null, 2)}\n`;
}

describe('S03 flag-off golden (generated at base 6d00b80)', () => {
  it('reproduces FakeLLM prompts, reply requests and Anthropic bodies with every flag unset', async () => {
    vi.stubEnv('TIREH_CACHED_PROMPT', '');
    vi.stubEnv('TIREH_PROMPT_SYSTEM_TAIL', '');
    await expect(await golden()).toMatchFileSnapshot(SNAPSHOT);
  });

  it('reproduces the same golden with only TIREH_PROMPT_SYSTEM_TAIL=1', async () => {
    vi.stubEnv('TIREH_CACHED_PROMPT', '');
    vi.stubEnv('TIREH_PROMPT_SYSTEM_TAIL', '1');
    await expect(await golden()).toMatchFileSnapshot(SNAPSHOT);
  });
});
